// check in Table so late interests, remaps and budget fallback cannot be
// mistaken for persistent JIT coverage by an external cache.
bool fully_watched(const Token &t) const noexcept {
    std::lock_guard lock(mutex_);
    if (!collecting_ || !persistent_ || !stats_.observing || stats_.failed
        || t.epoch != interval_serial_ || t.resource >= resources_.size()) return false;
    const auto &r = resources_[t.resource];
    if (!r.covered || t.mapping_version != r.mapping_version
        || t.cpu_version != r.cpu_version || t.host_version != r.host_version) return false;
    return std::all_of(r.groups.begin(), r.groups.end(), [&](uint32_t id) {
        const auto &g = groups_[id];
        return g.armed && g.epoch == stats_.epoch && !g.aliases.empty();
    });
}
