uint64_t resource_texture_hash(uint8_t **table, uint32_t address, const void *pixels,
    uint64_t size, const void *palette, uint64_t palette_size, ResourceHash hash) {
    if (!resource_controls_ran) {
        resource_controls_ran = true;
        resource_controls_ok = reuse::dynamic_controls(hash);
        record("resource_reuse", "dynamic_core", resource_controls_ok ? "pass" : "fail",
            "production hash callback; private pixels/palette, tracked mutation, same-value, lifetime, withdrawn coverage and missing-writer negative; no GPU injection");
    }
    const auto full = [&]() {
        tracelab::Scope measured(tracelab::Metric::TextureHash, tracelab::Domain::Render, size);
        return (pixels && size ? hash(pixels,size) : 0) ^ (palette && palette_size ? hash(palette,palette_size) : 0);
    };
    if (!resource_run.active) return full();
    const reuse::Input input{reinterpret_cast<uintptr_t>(pixels),reinterpret_cast<uintptr_t>(palette),size,palette_size,1};
    const auto snapshot = [&]() noexcept {
        const auto token = live_watch.before(table,address,pixels,size,palette,palette_size);
        const auto admission = reuse::source_policy.admit(input);
        reuse::WriteStamp external{};
        external.valid = admission.supported; external.lifetime = admission.lifetime;
        external.host = admission.generation;
        // Coverage comes from the pinned native-producer profile plus persistent
        // GPU/write-destination exclusion, NOT an empty asynchronous ledger.
        return reuse::observer_evidence(live_watch,token,external,
            admission.supported && resource_controls_ok ? reuse::CompleteCoverage : 0u);
    };
    return resource_run.cache.evaluate(input,snapshot,full);
}

