# then invert only this stage below; later stages may extend it.
tail = own
following = False
for rp in engine.RECIPES:
    if rp.name == 'switch-declaration-resolution.json':
        following = True; continue
    if following:
        for spec in json.loads(rp.read_text())['files']:
            if spec['path'] == item['path']: tail = engine.transform(tail, spec['replacements'])
assert tail == final, item['path']
